import{z as c,x as n,o as e,c as A,q as E,j as t,D as r,d as i,s as o,S as l,b as d}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"discard 与 TRIM","description":"","frontmatter":{"title":"discard 与 TRIM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/discard-trim.md","filePath":"cs/discard-trim.md","lastUpdated":1791063341000}'),B={name:"cs/discard-trim.md"};function p(T,a,m,C,f,D){const s=n("Mermaid");return e(),A("div",null,[a[2]||(a[2]=E('<h1 id="discard-与-trim" tabindex="-1">discard 与 TRIM <a class="header-anchor" href="#discard-与-trim" aria-label="Permalink to &quot;discard 与 TRIM&quot;">​</a></h1><div class="epigraph"><p>discard/TRIM 告诉闪存哪些 LBA 不再包含有效数据，FTL 才好在垃圾回收时不搬它们。</p><footer>—— 据 ATA TRIM / NVMe deallocate；Linux mount discard 与 fstrim 文档</footer></div><p><a href="/cs/write-barrier-fua">上一课</a>管「必须留下的写」。删除文件、<a href="/cs/sparse-files">穿孔</a>、<a href="/cs/thin-provisioning">thin</a> 还块之后，SSD 若仍当有效，GC 会搬垃圾。缺口是 <strong>discard</strong>：FS 空闲 → 块层 TRIM → 设备 deallocate。存储栈课序在此收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>POSIX <code>unlink</code> 只改 FS 元数据。SSD 的 FTL 不知 inode。<code>FITRIM</code>/<code>fstrim</code> 或挂载 <code>discard</code>：对空闲范围发 discard bio。缺口：实时 discard 可能拖慢删除；批量 fstrim 更常见；安全上 TRIM 可能向下层泄露空闲图（<a href="/cs/dm-crypt">dm-crypt</a> 有 <code>allow_discards</code> 旋钮）；RAID/thin 必须把 discard 正确 remap，否则剪错盘。本课不把 zoned 复位当 TRIM 的同义词，只点相近。</p><p><span class="marginnote">NVMe Dataset Management / deallocate、SCSI UNMAP 是同一意图的命令。不支持则 FS 仍能工作，只是写放大变差。</span></p><p><span class="marginnote">术语翻译：FTL（Flash Translation Layer，闪存转换层）是 SSD 内部的「翻译官」，把主机说的逻辑块号 LBA 映射到闪存物理页。麻烦在于闪存不能原地覆盖写，只能整块擦、逐页写——于是旧版本数据会一直赖在物理页里，直到垃圾回收来清。「写放大」就是：主机写 1 MB，闪存实际擦写了不止 1 MB。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>e2fsck 不管 TRIM。运行时：<code>fstrim /</code> 查询 FS 空闲 extent，发 discard。thin：discard 取消映射并可能对池成员再 TRIM。对照 <a href="/cs/fsck">fsck</a>：fsck 重建位图后应再 trim，以免位图与 FTL 长期偏离。对照预读：discard 不是读。</p>',9)),(e(),t(l,null,{default:r(()=>[o(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREE%5B%22FS%20%E7%A9%BA%E9%97%B2%E8%8C%83%E5%9B%B4%22%5D%20--%3E%20DC%5B%22discard%20bio%22%5D%0A%20%20DC%20--%3E%20MAP%5B%22dm%2Fmd%20remap%22%5D%0A%20%20MAP%20--%3E%20CMD%5B%22TRIM%2Fdeallocate%22%5D%0A%20%20CMD%20--%3E%20FTL%5B%22FTL%20%E4%B8%8D%E6%90%AC%E8%BF%99%E4%BA%9B%E9%A1%B5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=d("h2",{id:"机制",tabindex:"-1"},[i("机制 "),d("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=d("p",null,"TRIM 把 FS 空闲信息推到 FTL，是闪存上「诚实的空闲」。它不保证立刻擦除（安全擦除是另一命令），也不替代加密。不要写成硬件寿命营销。与配额：discard 后用量下降，记账要跟穿孔一样减。",-1)),(e(),t(l,null,{default:r(()=>[o(s,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20NO%5B%22%E6%97%A0%20TRIM%EF%BC%9AGC%20%E6%90%AC%E5%9E%83%E5%9C%BE%22%5D%0A%20%20%20%20B1%5B%22%E6%95%B0%E6%8D%AE%E5%9D%97%EF%BC%9A%E6%9C%89%E6%95%88%208%20%E9%A1%B5%20%2B%20%E5%9E%83%E5%9C%BE%2056%20%E9%A1%B5%22%5D%20--%3E%20GC1%5B%22GC%20%E4%B8%BA%E8%85%BE%E7%A9%BA%E5%9D%97%E6%90%AC%208%20%E9%A1%B5%E6%9C%89%E6%95%88%E6%95%B0%E6%8D%AE%22%5D%0A%20%20%20%20B2%5B%22%E5%9E%83%E5%9C%BE%E5%9D%97%EF%BC%9A%E6%9C%89%E6%95%88%200%20%E9%A1%B5%E4%BD%86%20FTL%20%E4%B8%8D%E7%9F%A5%E9%81%93%22%5D%20--%3E%20GC1%0A%20%20%20%20GC1%20--%3E%20WA1%5B%22%E7%99%BD%E6%90%AC%E7%9A%84%E9%A1%B5%EF%BC%9A%E5%86%99%E6%94%BE%E5%A4%A7%E9%AB%98%E3%80%81%E5%AF%BF%E5%91%BD%E6%8D%9F%E8%80%97%22%5D%0A%20%20end%0A%20%20subgraph%20YES%5B%22%E6%9C%89%20TRIM%EF%BC%9AGC%20%E5%8F%AA%E6%90%AC%E6%9C%89%E6%95%88%22%5D%0A%20%20%20%20C1%5B%22%E5%90%8C%E5%9D%97%EF%BC%9A56%20%E9%A1%B5%E5%B7%B2%20deallocate%22%5D%20--%3E%20GC2%5B%22GC%20%E7%9F%A5%E9%81%93%E5%85%A8%E6%98%AF%E5%9E%83%E5%9C%BE%22%5D%0A%20%20%20%20C2%5B%22%E6%9C%89%E6%95%88%208%20%E9%A1%B5%22%5D%20--%3E%20GC2%0A%20%20%20%20GC2%20--%3E%20WA2%5B%22%E5%8F%AA%E6%93%A6%E4%B8%8D%E6%90%AC%EF%BC%8C%E7%9B%B4%E6%8E%A5%E5%9B%9E%E6%94%B6%22%5D%0A%20%20end%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p>这张图回答「TRIM 到底替 GC 省了什么」：闪存擦除以块为单位，GC 想腾出一个空块，必须先把块里「还有效」的页搬到别处。数字实例：一个 64 页的块若无 TRIM 信息、裹着 56 页已删除文件的数据，GC 就要白搬 56 页；有 TRIM 则这 56 页标记为无效，直接擦掉——搬运量从 56 页降到 0。</p><p><span class="marginnote">常见误区：「发了 TRIM，数据就被安全销毁了」。TRIM 只是告诉 FTL「这些 LBA 不再有效」，FTL 通常让后续读返回零或旧垃圾，但物理页是否立刻擦掉、旧数据是否还躺在别的映射里，协议一概不承诺。要的是「删了就恢复不出来」，得用安全擦除命令或加密盘销毁密钥，TRIM 不算数。</span></p><p>网络下一单元：这些块 I/O 直觉有一部分会在网卡队列上重现——但对象换成包。</p><p>实现上：实时 discard 把删除变成同步设备命令，USB 桥接上会卡。fstrim.timer 批量做是发行版默认。加密盘默认不传 discard，以免泄露空闲图。 读法上只引用<a href="/cs/write-barrier-fua">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>discard 与 TRIM</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每次厂商的 TRIM 队列深度quirk。不保证 USB 桥接转发 UNMAP。文件系统与存储栈到此接到设备介质。下一单元从套接字缓冲的内核对象开始：sk_buff。</p><p>版本字段会变，课序钉的是机制对象「discard 与 TRIM」，不是某一主线内核的结构体名。 后课默认：空闲块可通知闪存。包在内核里的载体，下一课 sk_buff。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>discard/TRIM 把 FS 空闲告诉 FTL，降低写放大。</li><li>批量 fstrim 往往优于实时 discard；加密与 RAID 要小心传递。</li><li>网络栈从 sk_buff 起。</li><li>出处：ATA TRIM；NVMe；Linux fstrim；<em>OSTEP</em> SSD 章。</li></ul>',11))])}const F=c(B,[["render",p]]);export{h as __pageData,F as default};
